import { mkdir, writeFile } from 'node:fs/promises'
import { compileFromFile } from 'json-schema-to-typescript'
import { fileURLToPath } from 'node:url'

const destination = new URL('../src/generated/', import.meta.url)
await mkdir(destination, { recursive: true })
const source = new URL(
  '../../../../tests/cli/contract/switches.schema.json',
  import.meta.url,
)
const types = await compileFromFile(fileURLToPath(source), {
  additionalProperties: true,
  bannerComment:
    '/* Generated by npm run gen:types from tests/cli/contract/switches.schema.json. Do not edit. */',
})
await writeFile(new URL('switches.ts', destination), types)
console.log('Generated 1 schema module: src/generated/switches.ts')
await import('./generate-profile-aliases.mjs')
